import math


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError

    text = text.strip()

    if not text:
        raise ValueError("Empty string")

    # Handle negation
    negative = False
    if text.startswith('-'):
        negative = True
        text = text[1:].strip()
    elif text.startswith('+'):
        raise ValueError("Leading + not allowed")

    if not text:
        raise ValueError("Empty after negation")

    # Tokenize into (number, unit) pairs
    tokens = []
    i = 0
    while i < len(text):
        # Skip spaces between components
        while i < len(text) and text[i] == ' ':
            i += 1

        if i >= len(text):
            break

        # Read number (digits and optional decimal point)
        j = i
        while j < len(text) and (text[j].isdigit() or text[j] == '.'):
            j += 1

        if i == j:
            raise ValueError("Expected number")

        number_str = text[i:j]

        # Validate fraction format: must have digits on both sides
        if '.' in number_str:
            if number_str.startswith('.') or number_str.endswith('.'):
                raise ValueError("Invalid fraction format")

        # Check for space between number and unit
        if j < len(text) and text[j] == ' ':
            raise ValueError("Space between number and unit")

        # Read unit
        if j >= len(text):
            raise ValueError("No unit after number")

        if j + 1 < len(text) and text[j:j+2] == 'ms':
            unit = 'ms'
            j += 2
        elif text[j] in 'wdhms':
            unit = text[j]
            j += 1
        else:
            raise ValueError("Invalid unit")

        tokens.append((number_str, unit))
        i = j

    if not tokens:
        raise ValueError("No components")

    # Validate and convert tokens to milliseconds
    units_ms = {
        'w': 7 * 24 * 60 * 60 * 1000,  # 604800000
        'd': 24 * 60 * 60 * 1000,      # 86400000
        'h': 60 * 60 * 1000,           # 3600000
        'm': 60 * 1000,                # 60000
        's': 1000,                     # 1000
        'ms': 1
    }

    unit_order = ['w', 'd', 'h', 'm', 's', 'ms']

    last_unit_index = -1
    seen_units = set()
    total_ms = 0.0

    for idx, (number_str, unit) in enumerate(tokens):
        # Validate unit exists
        if unit not in units_ms:
            raise ValueError("Unknown unit")

        # Validate unit order (strictly descending)
        unit_index = unit_order.index(unit)
        if unit_index <= last_unit_index:
            raise ValueError("Units not in strictly descending order")

        # Validate no duplicate units
        if unit in seen_units:
            raise ValueError("Duplicate unit")

        last_unit_index = unit_index
        seen_units.add(unit)

        # Only last component can have fraction
        is_last = idx == len(tokens) - 1
        if '.' in number_str and not is_last:
            raise ValueError("Only last component can have fraction")

        # Add to total
        number_value = float(number_str)
        total_ms += number_value * units_ms[unit]

    # Round to nearest millisecond with halves rounding away from zero
    if total_ms >= 0:
        result = math.floor(total_ms + 0.5)
    else:
        result = -math.floor(-total_ms + 0.5)

    # Handle -0
    if result == 0:
        result = 0

    if negative:
        result = -result

    return result
